(() => {
  if (window.__biglwaBrandAssetsApplied) return;
  window.__biglwaBrandAssetsApplied = true;

  const A = {"ornate":"data:image/webp;base64,[... ELLIPSIZATION ...]","games":"data:image/webp;base64,","wordmark":"data:image/webp;base64,","wordmark":"data:image/webp;base64,"};

  const css = document.createElement('style');
  css.id = 'biglwa-brand-assets-style';
  css.textContent = `
    .brand,.login-brand{display:inline-flex!important;align-items:center!important;text-decoration:none!important;line-height:1!important}
    .biglwa-wordmark-img{display:block;width:auto;height:36px;max-width:190px;object-fit:contain}
    .login-brand .biglwa-wordmark-img{height:52px;max-width:260px}
    .policy-top .login-brand .biglwa-wordmark-img{height:39px;max-width:190px}
    .biglwa-login-emblem{display:block;width:min(280px,72%);height:auto;object-fit:contain;margin:18px 0 20px;filter:drop-shadow(0 8px 20px rgba(45,15,16,.12))}
    .biglwa-sidebar-emblem{display:block;width:116px;max-width:82%;height:auto;object-fit:contain;margin:0 auto 12px;opacity:.92;filter:drop-shadow(0 5px 12px rgba(45,15,16,.10))}
    .biglwa-games-card-logo{display:block;width:min(190px,72%);height:auto;object-fit:contain;margin:7px auto 11px;filter:drop-shadow(0 7px 12px rgba(45,35,25,.10))}
    .biglwa-games-module-logo{display:block;width:min(300px,66vw);height:auto;object-fit:contain;margin:18px auto 2px;filter:drop-shadow(0 10px 18px rgba(45,35,25,.10))}
    .games-card .quiz{margin-top:0}
    body.night-mode .biglwa-wordmark-img{filter:brightness(1.7) saturate(.9)}
    body.night-mode .biglwa-sidebar-emblem,body.night-mode .biglwa-login-emblem{filter:brightness(1.15) drop-shadow(0 7px 18px rgba(0,0,0,.22))}
    @media(max-width:620px){
      .biglwa-wordmark-img{height:30px;max-width:150px}
      .login-brand .biglwa-wordmark-img{height:42px;max-width:210px}
      .biglwa-login-emblem{width:min(230px,70%);margin:12px 0 16px}
      .biglwa-sidebar-emblem{width:92px}
    }
  `;
  document.head.appendChild(css);

  const makeImg = (cls, src, alt='') => {
    const img = document.createElement('img');
    img.className = cls;
    img.src = src;
    img.alt = alt;
    img.decoding = 'async';
    img.loading = 'eager';
    return img;
  };

  function applyWordmarks() {
    document.querySelectorAll('a.brand, a.login-brand').forEach(a => {
      if (a.dataset.biglwaWordmark === '1') return;
      a.textContent = '';
      a.appendChild(makeImg('biglwa-wordmark-img', A.wordmark, 'BIGLWA'));
      a.dataset.biglwaWordmark = '1';
      if (!a.getAttribute('aria-label')) a.setAttribute('aria-label','BIGLWA');
    });
  }

  function applyLoginEmblem() {
    const stage = document.querySelector('.login-stage');
    const copy = stage?.querySelector('.login-copy');
    if (!stage || !copy || stage.querySelector('.biglwa-login-emblem')) return;
    stage.insertBefore(makeImg('biglwa-login-emblem', A.ornate, 'BIGLWA emblem'), copy);
  }

  function applySidebarEmblem() {
    const bottom = document.querySelector('.sidebar-bottom');
    const themes = bottom?.querySelector('.sidebar-theme-controls');
    if (!bottom || !themes || bottom.querySelector('.biglwa-sidebar-emblem')) return;
    bottom.insertBefore(makeImg('biglwa-sidebar-emblem', A.ornate, 'BIGLWA emblem'), themes);
  }

  function applyGamesCardLogo() {
    const card = document.querySelector('#games');
    const quiz = card?.querySelector('.quiz');
    if (!card || !quiz || card.querySelector('.biglwa-games-card-logo')) return;
    card.insertBefore(makeImg('biglwa-games-card-logo', A.games, 'BIGLWA Games'), quiz);
  }

  function applyGamesModuleLogo() {
    const body = document.querySelector('#moduleWorkspaceBody');
    const route = document.querySelector('#moduleRouteName')?.textContent?.trim().toLowerCase();
    if (!body || route !== 'games') return;
    if (body.querySelector('.biglwa-games-module-logo')) return;
    const heading = body.querySelector('.module-heading');
    if (heading) heading.insertAdjacentElement('afterend', makeImg('biglwa-games-module-logo', A.games, 'BIGLWA Games'));
  }

  function applyAll() {
    applyWordmarks();
    applyLoginEmblem();
    applySidebarEmblem();
    applyGamesCardLogo();
    applyGamesModuleLogo();
  }

  let queued = false;
  const queueApply = () => {
    if (queued) return;
    queued = true;
    requestAnimationFrame(() => { queued = false; applyAll(); });
  };
  const observer = new MutationObserver(queueApply);
  observer.observe(document.documentElement, {subtree:true, childList:true});
  window.addEventListener('popstate', queueApply);
  document.addEventListener('click', e => {
    if (e.target.closest('#games,[data-open="games"],[data-module-launch="games"]')) setTimeout(queueApply, 20);
  }, true);
  applyAll();
})();
